// DONEZO LIBRARY DATA (Nov 20) — generated by build-library-data.py from ours-globals.json. Counts: 42 concepts, 11 cheat sheets, 36 project guides.
const LIBRARY_DATA = {"concepts": [{"subject": "Science", "items": [["photosynthesis", {"t": "Photosynthesis is how plants cook their own food. A plant takes in sunlight, water (from roots), and carbon dioxide (from air) and turns them into glucose — sugar for energy — plus oxygen, which it releases. It happens inside chloroplasts, using the green pigment chlorophyll.\n\nReal-world example: a tomato plant on a windowsill grows toward the light because light is literally one of its ingredients.\n\nMemory hook: \"Plants are chefs: light is the stove, water and air are the ingredients, sugar is the meal, oxygen is the steam.\"", "w": "The word itself explains it: \"photo\" = light, \"synthesis\" = putting together. Plants put things together using light."}], ["mitosis", {"t": "Mitosis is cell division for growth and repair: one cell → two identical cells, same chromosome count. Phases: Prophase (chromosomes condense), Metaphase (line up in the middle), Anaphase (pulled apart), Telophase (two nuclei form), then cytokinesis splits the cell.\n\nReal-world example: a scraped knee healing — mitosis is the repair crew.\n\nMemory hook: \"PMAT — Please Make Another Twin.\"", "w": "It works because DNA copies itself first (interphase), so each daughter cell gets the full instruction manual."}], ["meiosis", {"t": "Meiosis makes sex cells (eggs/sperm) with HALF the chromosomes, through two divisions — and shuffles genes (crossing over) so offspring differ. That’s why siblings aren’t clones.\n\nReal-world example: you got 23 chromosomes from each parent — meiosis is how that halving happened.\n\nMemory hook: \"Meiosis = My-oh-sis, half the chromosomes, twice the variety.\" Contrast: mitosis = identical twins; meiosis = shuffled deck.", "w": "Halving is required so fertilization (half + half) restores the full set instead of doubling every generation."}], ["gravity", {"t": "Gravity is mass attracting mass. Earth’s gravity accelerates falling objects at about 9.8 m/s² — after 1 second you fall at 9.8 m/s, after 2 seconds 19.6 m/s, speeding up the whole way down.\n\nReal-world example: the Moon’s gravity pulls Earth’s oceans into tides.\n\nMemory hook: \"9.8 — falling’s rate.\" College depth: Newton’s law F = G(m₁m₂)/r² — double the distance, quarter the force (inverse-square).", "w": "It works at every scale because mass itself bends how objects move through space — Newton described it, Einstein explained it."}], ["cell structure", {"t": "A cell is a tiny city. Nucleus = city hall (DNA instructions). Mitochondria = power plants (make ATP energy). Ribosomes = factories (build proteins). Cell membrane = border wall with gates (controls what enters/leaves). Cytoplasm = the city streets everything floats in.\n\nMemory hook: \"The nucleus is the boss, mitochondria bring the energy, the membrane mans the gates.\"", "w": "The city analogy works because each organelle really does have one job that keeps the whole system alive."}], ["newton’s laws", {"t": "Newton’s three laws describe motion: (1) objects keep their state unless a force acts — inertia; (2) force equals mass times acceleration, F = ma; (3) every action has an equal and opposite reaction.\n\nReal-world example: a rocket pushes exhaust down, and the exhaust pushes the rocket up — the third law in action.\n\nMemory hook: \"Push the ground away, and the ground pushes you into the sky.\"", "w": "Nearly every mechanics problem is one of the three laws wearing a costume; naming which law applies is half the solution."}], ["water cycle", {"t": "The water cycle is an endless loop powered by the sun: water evaporates from surfaces, condenses into clouds, falls as precipitation, and collects in bodies of water and groundwater.\n\nReal-world example: morning dew is condensation — the same step that builds clouds, happening on grass.\n\nMemory hook: \"The water in your glass is older than the dinosaurs — it just keeps cycling.\"", "w": "Every stage question is one stop on the same loop — evaporation, condensation, precipitation, collection."}]]}, {"subject": "Math", "items": [["fractions", {"t": "A fraction is a fair-sharing number. The denominator (bottom) says how many equal pieces the whole is cut into; the numerator (top) says how many pieces you have. 3/4 = a pizza cut into 4, you hold 3.\n\nReal-world example: a recipe calling for 1/2 cup of flour — half of the measuring cup.\n\nMemory hook: \"Denominator = Downstairs number = how many pieces Down there are.\" Adding fractions needs a common denominator because you can only add pieces of the same size.", "w": "Fractions work because they name amounts between whole numbers precisely — the bottom number defines the unit, the top counts the units."}], ["pythagorean theorem", {"t": "In any right triangle, the two shorter sides squared and added equal the longest side (the hypotenuse) squared: a² + b² = c². A 3-4-5 triangle always works: 9 + 16 = 25.\n\nReal-world example: checking a picture frame is square — measure the diagonal and compare with the theorem.\n\nMemory hook: \"Three-four-five, the triangle’s alive.\" For AP/College depth: it’s a special case of the law of cosines, and it defines distance in coordinate geometry: distance = √((x₂−x₁)² + (y₂−y₁)²).", "w": "It works because areas of squares built on the sides balance exactly — geometry you can prove by rearranging the same four triangles."}], ["quadratic equations", {"t": "A quadratic has x² in it, and its graph is a parabola (a U). Solve by factoring, completing the square, or the quadratic formula: x = (−b ± √(b² − 4ac)) / 2a. The discriminant (b² − 4ac) tells you the ending: positive = 2 solutions, zero = 1, negative = none (real).\n\nReal-world example: a ball’s height over time is quadratic — gravity curves it.\n\nMemory hook: Sing the formula to \"Pop Goes the Weasel\" — a genuine classic: \"x equals negative b, plus or minus the square root…\"", "w": "It works because every quadratic can be rewritten by completing the square — the formula is just that process pre-done."}], ["algebra", {"t": "Algebra is arithmetic with a mystery number. x is a box hiding a value; equations are balance scales — do the same thing to both sides and the scale stays true. Undo operations in reverse order (addition before multiplication’s inverse) to open the box.\n\nReal-world example: \"3 shirts + $7 shipping = $52 — what’s one shirt?\" is 3x + 7 = 52.\n\nMemory hook: \"Whatever you do to one side, do to the other — the scale never lies.\"", "w": "It works because equality is preserved under identical operations — the plug-back check proves your answer balances."}], ["probability", {"t": "Probability = favorable outcomes ÷ total outcomes, always between 0 (impossible) and 1 (certain). Flip a fair coin: P(heads) = 1/2. Independent events multiply: two heads in a row = 1/2 × 1/2 = 1/4.\n\nReal-world example: weather’s \"70% chance of rain\" means: of days like this, it rained on about 7 in 10.\n\nMemory hook: \"Want it over all of it.\" College depth: expected value = Σ(probability × payoff) — the math behind every game and insurance policy.", "w": "It works because counting equally-likely outcomes turns uncertainty into arithmetic."}], ["slope and linear equations", {"t": "A line’s slope is rise over run — how much y changes when x grows by 1. The equation y = mx + b packages the slope (m) and the starting value (b, the y-intercept) in one line.\n\nReal-world example: a taxi charging $3 plus $2 per mile is C = 2m + 3 — slope 2, intercept 3.\n\nMemory hook: \"m is the speed, b is the head start.\"", "w": "Most real-world linear problems are just identifying the rate and the starting amount — find those two numbers and the equation writes itself."}], ["exponents and powers", {"t": "An exponent counts repeated multiplication: 2^5 = 2×2×2×2×2 = 32. Key rules: multiply same bases by adding exponents, divide by subtracting, and anything to the power 0 equals 1.\n\nReal-world example: bacteria doubling hourly follow powers of 2 — after 10 hours, one cell becomes 2^10 = 1,024.\n\nMemory hook: \"Exponents are multiplication with a counter.\"", "w": "Growth, decay, scientific notation, and half of algebra errors trace back to these three rules."}]]}, {"subject": "History", "items": [["the civil war", {"t": "The American Civil War (1861–1865): eleven Southern states seceded to form the Confederacy, chiefly to preserve slavery; the Union fought to preserve the nation. Key turns: Antietam (bloodiest day, 1862), the Emancipation Proclamation (1863), Gettysburg (1863), and Lee’s surrender at Appomattox (1865). The 13th Amendment abolished slavery.\n\nReal-world example: Juneteenth (June 19, 1865) marks when the last enslaved people in Galveston, Texas learned they were free.\n\nMemory hook: \"1861–65, the Union survived: 13th set them free.\"", "w": "Historians weigh causes by evidence: secession declarations themselves name slavery as the central cause."}], ["world war ii", {"t": "World War II (1939–1945): Axis powers (Germany, Italy, Japan) vs the Allies (including the US, UK, USSR). Ignited by Nazi Germany’s invasion of Poland. Turning points: Stalingrad (1943), D-Day (June 6, 1944), and in the Pacific, Midway (1942). Ended 1945 — followed by the UN’s founding and the Cold War.\n\nMemory hook: \"D-Day: June 6, 44 — the door to Europe’s floor.\" AP depth: connect causes to WWI’s Treaty of Versailles and the Great Depression’s radicalization.", "w": "Historians treat it as a global system failure: unresolved WWI grievances + economic collapse + appeasement."}], ["declaration of independence", {"t": "Written mainly by Thomas Jefferson and adopted July 4, 1776, the Declaration of Independence announced the American colonies’ separation from Britain and grounded it in natural rights — life, liberty, and the pursuit of happiness — and the consent of the governed.\n\nReal-world example: its grievance list against King George III reads like an indictment, count by count.\n\nMemory hook: \"1776: the colonies’ breakup letter, with receipts.\"", "w": "Its ideas echo through the Constitution and later movements — natural rights and consent of the governed became America’s founding argument."}], ["civil rights movement", {"t": "The mid-20th-century Civil Rights Movement used boycotts, sit-ins, marches, and court cases to end legal segregation and secure voting rights, winning the Civil Rights Act of 1964 and the Voting Rights Act of 1965.\n\nReal-world example: the Montgomery bus boycott lasted 381 days and ended with desegregated buses.\n\nMemory hook: \"Rights were not given; they were marched for.\"", "w": "It is the template later movements copied — nonviolent pressure plus litigation plus legislation."}], ["great depression", {"t": "Beginning with the 1929 stock market crash, the Great Depression brought bank failures, unemployment near 25%, and deflation. The New Deal answered with relief programs, financial regulation, and Social Security.\n\nReal-world example: when banks failed, depositors lost everything — which is why deposits are insured today.\n\nMemory hook: \"1929: the economy fell down the stairs for a decade.\"", "w": "Modern economic policy was largely invented as a response to it — the Depression is the before picture for how governments handle crashes."}], ["cold war", {"t": "From 1945 to 1991, the United States and the Soviet Union competed for global influence without fighting each other directly — through alliances, proxy wars, an arms race, and the space race — under the shadow of nuclear weapons.\n\nReal-world example: the Cuban Missile Crisis of 1962 brought the two sides closest to direct war.\n\nMemory hook: \"A war fought everywhere except between the two main fighters.\"", "w": "It explains NATO, Korea, Vietnam, and the map of alliances still in place today."}], ["industrial revolution", {"t": "Starting in late-1700s Britain, the Industrial Revolution used steam power and factories to move production from homes and workshops to machines and cities, transforming work, transportation, and population patterns.\n\nReal-world example: railroads shrank a cross-country trip from months to days.\n\nMemory hook: \"Muscles to machines: the world sped up and moved to the city.\"", "w": "Urbanization, labor unions, pollution, and modern consumer goods all begin here."}]]}, {"subject": "Economics", "items": [["supply and demand", {"t": "Prices are a tug-of-war. Demand = how much buyers want something; supply = how much sellers offer. Scarce + wanted = price rises. Plenty + unwanted = price falls. Where the curves cross is the equilibrium price.\n\nReal-world example: concert tickets for a tiny venue sell out and resale prices explode — demand huge, supply fixed.\n\nMemory hook: \"Scarce and wanted? Price is haunted (by going up).\" College depth: shifts of the curves (income, tastes, input costs) move equilibrium; movements ALONG a curve are just price changes.", "w": "It works because price is a signal: it rations scarce goods to the buyers who value them most, automatically."}], ["inflation", {"t": "Inflation is a general rise in prices over time, which shrinks what each dollar buys. Central banks typically aim for about 2% a year.\n\nReal-world example: at 3% inflation, a $100 basket of goods costs $103 next year.\n\nMemory hook: \"Inflation is your money on a slow leak.\"", "w": "Interest rates, raises, and investing decisions make sense only relative to inflation — a 3% raise during 5% inflation is really a pay cut."}], ["interest and compound growth", {"t": "Interest is the price of borrowing money. Compound interest pays interest on interest, so balances (or debts) grow faster over time.\n\nReal-world example: $1,000 at 5% compounded yearly becomes about $1,629 in 10 years — not $1,500.\n\nMemory hook: \"Compounding: your money starts hiring its own workers.\"", "w": "It is the engine behind both retirement growth and credit-card debt traps — the same math, working for you or against you."}], ["opportunity cost", {"t": "Every choice costs the best alternative you gave up — that forgone alternative is the opportunity cost.\n\nReal-world example: an hour spent gaming costs the hour of studying (or sleep) it replaced.\n\nMemory hook: \"Every yes is a no to something else.\"", "w": "It turns vague \"is it worth it?\" questions into concrete comparisons: this, versus the best other thing."}], ["taxes", {"t": "Taxes fund public goods. The main types: income tax (on earnings), sales tax (on purchases), and payroll taxes (Social Security and Medicare, taken from paychecks).\n\nReal-world example: a $500 paycheck with $65 withheld shows payroll and income taxes taken out before the money arrives.\n\nMemory hook: \"Taxes are the membership fee for roads, schools, and firefighters.\"", "w": "Reading a first pay stub stops being confusing once the categories are clear — gross pay minus these withholdings is what actually lands."}], ["budgeting and the 50/30/20 rule", {"t": "A budget assigns income before it is spent. The 50/30/20 guideline suggests roughly 50% needs, 30% wants, and 20% savings and debt payoff.\n\nReal-world example: on $400 a month from a part-time job, that is $200 needs, $120 wants, $80 saved.\n\nMemory hook: \"Tell your money where to go before it disappears.\"", "w": "Percentages scale to any income — the same split works on $400 a month or $4,000."}], ["credit scores", {"t": "A credit score summarizes how reliably a person has borrowed and repaid. Paying on time and keeping balances low raise it, and higher scores unlock lower interest rates.\n\nReal-world example: the same car loan can cost thousands more in interest at a low score than at a high one.\n\nMemory hook: \"Your score is your financial reputation, in one number.\"", "w": "It explains why small habits — one late payment — have outsized future costs."}]]}, {"subject": "Spanish", "items": [["spanish verbs", {"t": "Spanish verbs change endings by WHO does the action. For regular -ar verbs (hablar): yo habl-o, tú habl-as, él/ella habl-a, nosotros habl-amos, ellos habl-an. The stem (habl-) carries the meaning; the ending carries the person.\n\nReal-world example: \"Yo hablo\" vs \"Ellos hablan\" — same verb, the ending tells you who.\n\nMemory hook: \"O, as, a, amos, an — chant it like a drumbeat.\" Irregular stars like ser (to be) and ir (to go) must be memorized cold — they’re the most-tested.", "w": "Endings do the job English gives to pronouns — that’s why Spanish speakers can drop the pronoun entirely."}], ["ser vs estar", {"t": "Spanish has two verbs for \"to be\": ser for identity, origin, and lasting traits; estar for states, feelings, and location.\n\nReal-world example: \"Ella es alta\" (she is tall — ser) vs. \"Ella está cansada\" (she is tired — estar).\n\nMemory hook: \"Ser is what it IS; estar is how it IS right now.\"", "w": "Choosing correctly is the single most common beginner error, and the identity/state split resolves most cases."}], ["present tense regular verbs", {"t": "Regular -ar, -er, and -ir verbs follow predictable endings: hablar → hablo, hablas, habla; comer → como, comes, come; vivir → vivo, vives, vive.\n\nReal-world example: \"Nosotros estudiamos\" = we study.\n\nMemory hook: \"Learn three patterns, unlock thousands of verbs.\"", "w": "Regular verbs are the bulk of everyday speech — master the three patterns and most sentences open up."}], ["gender and articles", {"t": "Every Spanish noun is masculine or feminine; el/la (the) and un/una (a) must match the noun, and adjectives agree too.\n\nReal-world example: \"la casa blanca\" — the white house, all feminine.\n\nMemory hook: \"The article is the noun’s name tag — copy it everywhere.\"", "w": "Agreement errors are what make beginner sentences sound off even when the vocabulary is right."}], ["spanish question words", {"t": "Spanish question words: qué (what), quién (who), cuándo (when), dónde (where), por qué (why), cómo (how), cuánto (how much) — all carry written accents in questions.\n\nReal-world example: \"¿Dónde está la biblioteca?\" — where is the library?\n\nMemory hook: \"Questions wear accent hats.\"", "w": "Recognizing the question word tells you what kind of answer to listen for."}], ["numbers and time", {"t": "Uno through cien cover counting. Telling time uses \"Es la una\" for one o’clock and \"Son las dos / tres...\" for later hours, with \"y media\" for half past.\n\nReal-world example: \"Son las tres y media\" = 3:30.\n\nMemory hook: \"One o’clock is single (es la una); the rest are plural (son las).\"", "w": "Time and numbers appear in nearly every real conversation — these are among the highest-use patterns in the language."}], ["common courtesy phrases", {"t": "Por favor (please), gracias (thank you), perdón (excuse me), buenos días (good morning), and ¿cómo estás? (how are you?) open almost every interaction.\n\nReal-world example: adding \"por favor\" and \"gracias\" transforms a demand into a request.\n\nMemory hook: \"Five phrases buy goodwill in any Spanish-speaking place on Earth.\"", "w": "Politeness formulas are memorized whole, so fluency is not required to use them well."}]]}, {"subject": "English", "items": [["essay writing", {"t": "An essay is an argument with manners. Thesis = your claim. Each body paragraph = one reason + evidence + analysis (\"this shows that…\"). The analysis sentences are where grades are won — evidence alone is just quoting.\n\nReal-world example: a lawyer’s closing argument is an essay out loud: claim, evidence, \"and that proves…\"\n\nMemory hook: \"Claim it, cite it, explain it — every paragraph, every time.\"", "w": "It works because readers (and graders) track claims, not facts. Structure makes your thinking visible."}], ["thesis statements", {"t": "A thesis is the one-sentence claim an essay will prove, usually at the end of the introduction. A strong thesis is arguable, specific, and previewing.\n\nReal-world example: \"School should start later because teen sleep cycles shift at puberty, later starts improve grades, and districts that switched saw fewer car accidents.\"\n\nMemory hook: \"A thesis is a promise the essay must keep.\"", "w": "Every paragraph can be checked against it — if a paragraph doesn’t serve the thesis, it doesn’t belong."}], ["subject-verb agreement", {"t": "Singular subjects take singular verbs and plural subjects take plural verbs, no matter what phrases sit between them.\n\nReal-world example: \"The box of chocolates was (not were) on the table\" — the subject is box.\n\nMemory hook: \"Find the real subject; ignore the crowd around it.\"", "w": "It is among the most-tested grammar rules on the SAT/ACT and the most common essay error."}], ["commas in a series", {"t": "Use commas to separate three or more items in a list, and after introductory phrases.\n\nReal-world example: \"After the game, we ate pizza, wings, and fries.\"\n\nMemory hook: \"Commas are traffic signals: they keep ideas from crashing.\"", "w": "These two rules cover the majority of comma questions and comma errors."}], ["their there they’re", {"t": "Their = possession (their car), there = place (over there), they’re = they are.\n\nReal-world example: \"They’re parking their car over there.\"\n\nMemory hook: \"They’re = they are; if ‘they are’ fits, it is right.\"", "w": "The substitution test settles the most common homophone mix-up in student writing."}], ["run-ons and fragments", {"t": "A fragment is an incomplete thought punctuated as a sentence; a run-on joins two complete thoughts with no or weak punctuation. Fix run-ons with a period, a semicolon, or a comma plus and/but/so.\n\nReal-world example: Fragment: \"Because I was late.\" Run-on fixed: \"I was late; the bus had left.\"\n\nMemory hook: \"Every sentence needs a complete thought with a door between clauses.\"", "w": "These two errors account for most sentence-boundary points on tests."}], ["figurative language", {"t": "Similes compare with like/as, metaphors compare directly, personification gives human traits to non-humans, and hyperbole exaggerates for effect.\n\nReal-world example: \"The wind whispered\" is personification; \"her smile was sunshine\" is a metaphor.\n\nMemory hook: \"Figurative language is the author’s special effects budget.\"", "w": "Naming the device is the first step to explaining its effect — and effect questions are where the points are."}]]}], "sheets": [{"id": "algebra", "title": "Algebra Essentials", "subject": "Math", "icon": "➗", "kw": "equation slope exponent factor quadratic variable linear solve", "blurb": "Solving, slope, exponents, and quadratics — the moves behind almost every algebra test.", "groups": [{"h": "Solving equations", "items": ["<b>Golden rule:</b> whatever you do to one side, do to the other — the equation stays balanced.", "<b>Undo in reverse:</b> peel off addition/subtraction first, then multiplication/division, then powers.", "<b>ax + b = c</b> → x = (c − b) ÷ a. Two moves, done.", "<b>Variables on both sides?</b> Collect all the x terms on one side first, then undo.", "<b>Check by plugging back in</b> — if both sides match, it is right. No exceptions."]}, {"h": "Slope & lines", "items": ["<b>Slope</b> m = (y₂ − y₁) ÷ (x₂ − x₁) — rise over run.", "<b>Slope-intercept:</b> y = mx + b. m is the slope, b is where the line crosses the y-axis.", "<b>Point-slope:</b> y − y₁ = m(x − x₁) — build a line from one point and a slope.", "<b>Parallel lines</b> have equal slopes. <b>Perpendicular lines</b> have slopes that multiply to −1.", "Horizontal line: slope 0. Vertical line: slope undefined."]}, {"h": "Exponents & powers", "items": ["x<sup>a</sup> · x<sup>b</sup> = x<sup>a+b</sup> — multiply powers, add exponents.", "x<sup>a</sup> ÷ x<sup>b</sup> = x<sup>a−b</sup> — divide powers, subtract exponents.", "(x<sup>a</sup>)<sup>b</sup> = x<sup>a·b</sup> — power of a power, multiply.", "x<sup>0</sup> = 1 (for any x ≠ 0). x<sup>−a</sup> = 1 ÷ x<sup>a</sup>.", "Watch the base: (−2)² = 4, but −2² = −4. Parentheses change everything."]}, {"h": "Factoring & quadratics", "items": ["<b>Difference of squares:</b> a² − b² = (a + b)(a − b).", "<b>Trinomial:</b> x² + bx + c → find two numbers that multiply to c and add to b.", "<b>Quadratic formula:</b> x = [−b ± √(b² − 4ac)] ÷ 2a — works on every quadratic, every time.", "<b>Discriminant</b> b² − 4ac: positive = 2 solutions, zero = 1, negative = none (real).", "A factored form (x − r)(x − s) = 0 means the solutions are x = r and x = s."]}], "example": {"t": "Solve 3x + 5 = 20", "lines": ["Subtract 5 from both sides → 3x = 15.", "Divide both sides by 3 → x = 5.", "Check: 3(5) + 5 = 20 ✓ — balanced, so it is right."]}, "why": "Algebra is just undoing operations in reverse order — learn the undo moves once and every equation becomes the same puzzle."}, {"id": "geometry", "title": "Geometry Formulas", "subject": "Math", "icon": "📐", "kw": "area perimeter volume circle triangle angle surface circumference", "blurb": "Area, perimeter, volume, and angle rules for every shape school throws at you.", "groups": [{"h": "Area", "items": ["<b>Rectangle:</b> A = l × w · <b>Square:</b> A = s²", "<b>Triangle:</b> A = ½ × b × h — half of the rectangle around it.", "<b>Circle:</b> A = πr² — radius squared, times pi.", "<b>Parallelogram:</b> A = b × h (use the vertical height, not the slanted side).", "<b>Trapezoid:</b> A = ½ × (b₁ + b₂) × h — average the two bases, times height."]}, {"h": "Perimeter & circumference", "items": ["<b>Perimeter:</b> add every side — it is just the fence around the shape.", "<b>Circle circumference:</b> C = 2πr, or C = πd with the diameter.", "Radius = half the diameter. Mixing them up is the #1 circle error.", "Units: perimeter is a length (cm), area is squares (cm²). Label them."]}, {"h": "Volume & surface", "items": ["<b>Box / prism:</b> V = l × w × h — base area times height.", "<b>Cylinder:</b> V = πr²h — circle area, stretched up.", "<b>Cone:</b> V = ⅓πr²h — exactly one-third of the matching cylinder.", "<b>Sphere:</b> V = (4/3)πr³ · Surface area = 4πr².", "<b>Pyramid:</b> V = ⅓ × (base area) × h."]}, {"h": "Triangles & angles", "items": ["Angles in any triangle add to <b>180°</b>.", "<b>Pythagorean theorem:</b> a² + b² = c² — right triangles only, c is the hypotenuse.", "Angles on a straight line add to 180°. Around a point: 360°.", "<b>Similar triangles:</b> same angles, sides in equal ratio — set up a proportion.", "Exterior angle of a triangle = the sum of the two opposite interior angles."]}], "example": {"t": "Area of a circle with radius 7", "lines": ["A = πr² = π × 7² = 49π ≈ 153.9 square units.", "Diameter would be 14 — if a problem gives you 14, halve it before you square anything."]}, "why": "Every geometry formula is a picture in disguise — if you can sketch the shape, you can rebuild the formula right on the test."}, {"id": "fractions", "title": "Fractions & Percents", "subject": "Math", "icon": "½", "kw": "fraction percent decimal ratio proportion convert add multiply divide", "blurb": "Fractions, decimals, and percents are one number in three outfits — convert fluently and problems shrink.", "groups": [{"h": "Fraction moves", "items": ["<b>Add / subtract:</b> get a common denominator first, then work on the numerators only.", "<b>Multiply:</b> straight across — top × top, bottom × bottom. No common denominator needed.", "<b>Divide:</b> flip the second fraction and multiply (keep–change–flip).", "<b>Simplify:</b> divide top and bottom by the same number until you cannot anymore.", "<b>Mixed ↔ improper:</b> 2¾ = 11/4 (multiply, add, keep the denominator)."]}, {"h": "Fractions ↔ decimals ↔ percents", "items": ["Fraction → decimal: divide the top by the bottom. ¾ = 0.75.", "Decimal → percent: move the point two places right. 0.75 = 75%.", "Percent → fraction: put it over 100 and simplify. 75% = 75/100 = ¾.", "Memorize the regulars: ½ = 50%, ¼ = 25%, ⅕ = 20%, ⅛ = 12.5%, ⅓ ≈ 33.3%."]}, {"h": "Percent problems", "items": ["<b>“Percent of”</b> = turn the percent into a decimal, then multiply. 20% of 60 = 0.20 × 60 = 12.", "<b>Percent change</b> = (new − old) ÷ old × 100. Always divide by the ORIGINAL.", "<b>Discount:</b> price × (1 − rate). 30% off $50 → 50 × 0.70 = $35.", "<b>Tax / tip:</b> price × (1 + rate). 8% tax on $50 → 50 × 1.08 = $54.", "<b>Find the whole:</b> part ÷ percent (as a decimal). 12 is 20% of what? 12 ÷ 0.20 = 60."]}, {"h": "Ratios & proportions", "items": ["A ratio a:b compares parts — scale both sides by the same number to keep it equal.", "<b>Proportion:</b> a/b = c/d → cross-multiply: a·d = b·c.", "Unit rate = the “per 1” version: divide until the denominator is 1.", "Map scales and recipes are proportions in costume — same cross-multiply move."]}], "example": {"t": "What is 15% of 80?", "lines": ["15% = 0.15 as a decimal.", "0.15 × 80 = 12.", "Sanity check: 10% of 80 is 8, 5% is 4 — 8 + 4 = 12 ✓."]}, "why": "Fractions, decimals, and percents are one number wearing three outfits — once converting is automatic, every one of these problems gets shorter."}, {"id": "biology", "title": "Biology Basics", "subject": "Science", "icon": "🧬", "kw": "cell photosynthesis genetics dna evolution organism mitosis punnett", "blurb": "Cells, energy, genetics, and systems — the backbone facts of every bio course.", "groups": [{"h": "The cell", "items": ["<b>Cell theory:</b> all living things are made of cells; cells come from cells; the cell is life’s basic unit.", "<b>Mitochondria</b> make ATP (energy). <b>Chloroplasts</b> run photosynthesis — plant cells have both.", "<b>Nucleus</b> holds DNA — the instruction manual. <b>Ribosomes</b> build proteins from those instructions.", "<b>Cell membrane</b> controls what enters and leaves — selectively permeable.", "Plant cells have a rigid <b>cell wall</b> and one big vacuole; animal cells do not."]}, {"h": "Energy: photosynthesis & respiration", "items": ["<b>Photosynthesis:</b> 6CO₂ + 6H₂O + sunlight → C₆H₁₂O₆ + 6O₂. Plants store light energy as sugar.", "<b>Cellular respiration:</b> C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP. Nearly the reverse — it releases the stored energy.", "Photosynthesis stores energy; respiration spends it. Every living cell respires.", "ATP is the spendable energy currency — glucose is the savings account."]}, {"h": "Genetics", "items": ["DNA → RNA → protein: the central dogma. Genes are DNA stretches that code for proteins.", "<b>Alleles:</b> versions of a gene. Dominant (capital) masks recessive (lowercase).", "Genotype = the letters (Bb). Phenotype = what shows (brown eyes).", "<b>Mitosis:</b> one cell → two identical cells (growth & repair). <b>Meiosis:</b> → four varied sex cells with half the chromosomes.", "Punnett squares predict offspring odds — each box is an equally likely outcome."]}, {"h": "Systems & ecology", "items": ["Levels: cell → tissue → organ → organ system → organism.", "<b>Homeostasis:</b> keeping internal conditions stable — temperature, water, blood sugar.", "Food chains move energy up; only about <b>10%</b> passes to the next level — the rest is lost as heat and life costs.", "Producers make food, consumers eat, decomposers recycle. Remove one and the web wobbles."]}], "example": {"t": "Punnett square: Bb × Bb (B = brown eyes, dominant)", "lines": ["Boxes: BB, Bb, Bb, bb → 3 of 4 show brown eyes, 1 of 4 shows the recessive trait.", "Genotype ratio 1 BB : 2 Bb : 1 bb. Phenotype ratio 3 : 1 — the classic Mendelian split."]}, "why": "Biology is systems inside systems — learn what each part does, and the diagrams start explaining themselves."}, {"id": "chemistry", "title": "Chemistry Basics", "subject": "Science", "icon": "⚗️", "kw": "periodic table atom trend mole bond reaction formula element electron", "blurb": "Atoms, periodic trends, bonding, and the handful of formulas that unlock most of chemistry.", "groups": [{"h": "Atoms & the table", "items": ["Atom = protons + neutrons in the nucleus, electrons around it. Protons define the element.", "<b>Atomic number</b> = number of protons. <b>Mass number</b> = protons + neutrons.", "Groups (columns) share behavior — Group 1 explodes in water, Group 18 (noble gases) barely reacts at all.", "Rows (periods) = electron shells being filled, left to right.", "Isotopes: same protons, different neutrons. Ions: electrons gained or lost — that is the charge."]}, {"h": "Periodic trends", "items": ["<b>Atomic radius:</b> grows down a group (more shells), shrinks across a period (stronger nuclear pull).", "<b>Ionization energy</b> (cost to remove an electron): rises across a period, falls down a group.", "<b>Electronegativity</b> (electron pull): rises across and up — fluorine is the strongest puller on the table.", "Metals sit left (they lose electrons), nonmetals right (they gain or share), metalloids on the staircase.", "Trend questions are pattern questions: find the element’s address, and the trend does the rest."]}, {"h": "Bonding & reactions", "items": ["<b>Ionic bond:</b> electrons transferred — metal + nonmetal, held by opposite charges.", "<b>Covalent bond:</b> electrons shared — usually between nonmetals.", "<b>Balance equations by atom count:</b> atoms are never created or destroyed, so both sides must match.", "Reaction types: synthesis (A + B → AB), decomposition (AB → A + B), combustion (fuel + O₂ → CO₂ + H₂O).", "Acids release H⁺, bases release OH⁻; pH below 7 = acid, 7 = neutral, above 7 = base."]}, {"h": "Formulas you will actually use", "items": ["<b>Moles:</b> n = mass ÷ molar mass. The mole is chemistry’s dozen — 6.02 × 10²³ particles.", "<b>Concentration:</b> M = moles ÷ liters of solution.", "<b>Percent composition:</b> (mass of element ÷ total mass) × 100.", "<b>Density:</b> d = m ÷ V — same triangle as physics.", "<b>Ideal gas:</b> PV = nRT — pressure × volume = moles × constant × temperature (in kelvin!)."]}], "example": {"t": "Balance H₂ + O₂ → H₂O", "lines": ["Count oxygens: 2 on the left, 1 on the right → put a 2 in front of H₂O.", "Now hydrogens: 4 on the right, 2 on the left → put a 2 in front of H₂.", "Balanced: 2H₂ + O₂ → 2H₂O. Check: H = 4 = 4 ✓, O = 2 = 2 ✓."]}, "why": "Chemistry runs on counting atoms — if the atoms balance and the trends point the right way, the answer is right."}, {"id": "physics", "title": "Physics Formulas", "subject": "Science", "icon": "🚀", "kw": "force velocity acceleration energy wave electricity newton motion momentum", "blurb": "Motion, forces, energy, waves, and circuits — with the units that tell you how to use each formula.", "groups": [{"h": "Motion", "items": ["<b>Speed / velocity:</b> v = d ÷ t (m/s). Velocity adds a direction.", "<b>Acceleration:</b> a = (v_final − v_initial) ÷ t (m/s²).", "Distance under steady acceleration: d = vᵢt + ½at².", "Free fall on Earth: a ≈ 9.8 m/s² downward — “g” shows up everywhere.", "Slope of a position–time graph = velocity. Slope of a velocity–time graph = acceleration."]}, {"h": "Forces & energy", "items": ["<b>Newton’s 2nd law:</b> F = m × a (newtons = kg·m/s²).", "<b>Weight:</b> W = m × g — mass stays the same everywhere, weight changes with gravity.", "<b>Work:</b> W = F × d (joules). No movement, no work — however hard you push.", "<b>Kinetic energy:</b> KE = ½mv². <b>Potential energy:</b> PE = mgh.", "<b>Momentum:</b> p = m × v — in collisions, total momentum is conserved.", "<b>Power:</b> P = W ÷ t (watts) — how fast work gets done."]}, {"h": "Waves & electricity", "items": ["<b>Wave speed:</b> v = f × λ — frequency times wavelength.", "Period and frequency flip: T = 1 ÷ f.", "<b>Ohm’s law:</b> V = I × R — voltage = current × resistance.", "<b>Electric power:</b> P = V × I.", "Series circuit: same current everywhere, resistances add. Parallel: same voltage, resistances shrink the total."]}, {"h": "Units & strategy", "items": ["Write the units next to every number — they are half the problem.", "If the units do not cancel into the unit you want, the formula setup is wrong. Fix it before computing.", "Convert first: km → m, hours → seconds, grams → kg.", "Every formula is a sentence: F = ma says “heavier or faster-changing things need more push.”"]}], "example": {"t": "A 2 kg cart accelerates at 3 m/s². What force?", "lines": ["F = m × a = 2 kg × 3 m/s² = 6 N.", "Units check: kg·m/s² is exactly the newton ✓."]}, "why": "Physics formulas are sentences about how the world behaves — read the units and the formula tells you how to use it."}, {"id": "grammar", "title": "Grammar Rules", "subject": "English", "icon": "✏️", "kw": "grammar punctuation comma apostrophe sentence subject verb its their homophone", "blurb": "The rules that fix 90% of writing errors — sentences, commas, apostrophes, and the classic mix-ups.", "groups": [{"h": "Sentence basics", "items": ["A complete sentence needs a <b>subject</b> (who/what) and a <b>verb</b> (does what) — and a complete thought.", "<b>Fragment:</b> a piece posing as a sentence (“Running down the street.”) — attach it or complete it.", "<b>Run-on:</b> two sentences fused. Fix with a period, a semicolon, or a comma + FANBOYS (for, and, nor, but, or, yet, so).", "Subject and verb must agree: “The dog runs,” not “The dog run.” Watch for phrases hiding between them."]}, {"h": "Punctuation that matters", "items": ["<b>Comma:</b> lists, after introductions, around extra info, and before FANBOYS joining two full sentences.", "<b>Apostrophe:</b> shows possession (the dog’s bowl) or a contraction (don’t). Never for plain plurals.", "<b>Semicolon:</b> joins two related complete sentences; it is a soft period.", "<b>Colon:</b> introduces a list or explanation — what follows must deliver on what came before.", "Quotation marks go around exact words spoken; commas and periods sit inside them (US style)."]}, {"h": "Common mix-ups", "items": ["<b>its</b> = belongs to it · <b>it’s</b> = it is. Test: expand it — if “it is” works, use the apostrophe.", "<b>their</b> = belongs to them · <b>there</b> = a place · <b>they’re</b> = they are.", "<b>your</b> = belongs to you · <b>you’re</b> = you are.", "<b>to</b> = direction · <b>too</b> = also / excessively · <b>two</b> = the number.", "<b>affect</b> is usually the verb (to influence) · <b>effect</b> is usually the noun (the result). RAVEN: Remember, Affect Verb, Effect Noun."]}, {"h": "Fix-it checklist", "items": ["Read it aloud — your ear catches what your eyes skip.", "One idea per sentence when a sentence starts fighting you.", "Capitalize names, places, and the start of sentences — never random nouns.", "Cut “very,” “really,” and “just” — they weaken more than they add."]}], "example": {"t": "Fix: “Its raining, and the team left there gear.”", "lines": ["“Its” → “It’s” (it is raining).", "“there” → “their” (the gear belongs to them).", "Fixed: “It’s raining, and the team left their gear.”"]}, "why": "Grammar rules are traffic signals for your reader — follow them and your meaning never crashes on the way."}, {"id": "essay", "title": "Essay Structure", "subject": "English", "icon": "🧱", "kw": "essay thesis paragraph evidence analysis introduction conclusion argument write", "blurb": "The skeleton every strong essay shares — thesis, evidence, analysis, and a close that lands.", "groups": [{"h": "The skeleton", "items": ["<b>Introduction:</b> hook → background → thesis. The thesis is the last sentence of the intro.", "<b>Body paragraphs:</b> one main point each — topic sentence, evidence, analysis, link back to the thesis.", "<b>Conclusion:</b> restate the thesis in new words, then widen out — why does this matter?", "Rule of three: three solid body points beat six thin ones.", "Every paragraph must answer: “How does this prove my thesis?” If it cannot, it does not belong."]}, {"h": "Thesis statements", "items": ["A thesis is a <b>claim someone could argue with</b> — “School should start later” argues; “School starts at 8” just states.", "Formula: topic + position + reasons. “Later start times improve grades, health, and safety.”", "Be specific: “pollution is bad” is fog; “plastic waste in oceans kills the food chain” is a claim.", "One sentence. If it needs “and also” three times, it is three theses fighting."]}, {"h": "Evidence & analysis", "items": ["Evidence = quotes, facts, examples. Analysis = what the evidence MEANS. Tests grade the analysis.", "The 2:1 rule: for every line of evidence, write about two lines of analysis.", "Introduce quotes — who said it and why they matter — never drop a quote in naked.", "Use the strongest evidence first; graders form opinions early."]}, {"h": "Transitions & closings", "items": ["Transitions are signposts: “First…”, “In contrast…”, “As a result…”, “Above all…”.", "Vary them — five paragraphs starting “Also” reads like a list, not an argument.", "Counterargument move: name the other side fairly, then answer it. It makes your side look stronger, not weaker.", "Close on an image or a stake, not “In conclusion, that is my essay.” End like you mean it."]}], "example": {"t": "Weak thesis → strong thesis", "lines": ["Weak: “Social media is interesting and has good and bad sides.” (No position — nothing to prove.)", "Strong: “Social media harms teen sleep and focus more than it helps connection, so schools should teach phone-free evenings.” (Position + reasons = a map for three body paragraphs.)"]}, "why": "An essay is an argument with a map — build the structure first and every sentence knows where it is going."}, {"id": "ushistory", "title": "U.S. History Timeline Highlights", "subject": "History", "icon": "🗽", "kw": "history timeline war declaration constitution civil rights revolution dates america", "blurb": "The anchor dates and turning points that U.S. history questions are built around — cause, event, effect.", "groups": [{"h": "Founding era · 1776–1800", "items": ["<b>1776</b> — Declaration of Independence: the colonies announce separation from Britain.", "<b>1783</b> — Revolutionary War won; Treaty of Paris recognizes the United States.", "<b>1788</b> — Constitution ratified: federal system, three branches, checks and balances.", "<b>1791</b> — Bill of Rights: the first ten amendments protect individual freedoms."]}, {"h": "Expansion & Civil War · 1800–1877", "items": ["<b>1803</b> — Louisiana Purchase doubles the country — and pushes expansion west.", "<b>1820s–40s</b> — Manifest Destiny: settlement spreads coast to coast, displacing Native nations.", "<b>1861–65</b> — Civil War: Union vs. Confederacy, fought primarily over slavery.", "<b>1863</b> — Emancipation Proclamation frees enslaved people in Confederate states.", "<b>1865</b> — 13th Amendment abolishes slavery; Reconstruction begins."]}, {"h": "Industry, war & depression · 1877–1945", "items": ["<b>Late 1800s</b> — Industrialization: factories, railroads, big cities, labor unions rise in response.", "<b>1920</b> — 19th Amendment: women win the vote nationwide.", "<b>1929</b> — Stock market crash → the Great Depression.", "<b>1930s</b> — FDR’s New Deal: relief, recovery, and reform programs reshape the federal role.", "<b>1941–45</b> — World War II: the U.S. joins after Pearl Harbor; the war ends in 1945."]}, {"h": "Modern America · 1945–today", "items": ["<b>1947–91</b> — Cold War: U.S. vs. Soviet Union — rivalry without direct war between them.", "<b>1954–68</b> — Civil Rights Movement: Brown v. Board (1954), Civil Rights Act (1964), Voting Rights Act (1965).", "<b>1969</b> — Apollo 11: first humans land on the Moon.", "<b>2001</b> — September 11 attacks reshape U.S. foreign and security policy.", "Through-line: every era is an argument about who “we the people” includes — and the circle keeps widening."]}], "example": {"t": "Cause → effect chain (a favorite test shape)", "lines": ["1929 crash → banks fail and jobs vanish → voters demand action → 1932: FDR elected → New Deal programs expand what the federal government does.", "Learn chains, not just dates — one event explaining the next is how essay questions are scored."]}, "why": "History questions are cause-and-effect in costume — anchor the turning-point dates and the whole story connects itself."}, {"id": "spanish", "title": "Spanish Essentials", "subject": "Spanish", "icon": "🌎", "kw": "spanish verbs ser estar conjugation numbers greetings vocabulary present tense", "blurb": "Core verbs, question words, numbers, and sentence builders — the Spanish that shows up on every quiz.", "groups": [{"h": "Must-know verbs · present tense", "items": ["<b>ser</b> (to be — identity): soy, eres, es, somos, son.", "<b>estar</b> (to be — state/location): estoy, estás, está, estamos, están.", "<b>tener</b> (to have): tengo, tienes, tiene, tenemos, tienen.", "<b>ir</b> (to go): voy, vas, va, vamos, van.", "Regular endings — <b>-ar</b>: -o, -as, -a, -amos, -an · <b>-er</b>: -o, -es, -e, -emos, -en · <b>-ir</b>: -o, -es, -e, -imos, -en.", "ser = what something IS (origin, traits, time). estar = how/where something is right now (feelings, location)."]}, {"h": "Question words & greetings", "items": ["¿Qué? = what · ¿Quién? = who · ¿Dónde? = where · ¿Cuándo? = when · ¿Por qué? = why · ¿Cómo? = how · ¿Cuánto? = how much.", "Hola = hello · Buenos días = good morning · Gracias = thank you · Por favor = please · De nada = you’re welcome.", "¿Cómo estás? = How are you? → Estoy bien / cansado(a) / enfermo(a).", "Question marks come in pairs: ¿ … ? — and accents on question words are required."]}, {"h": "Numbers & time", "items": ["1 uno · 2 dos · 3 tres · 4 cuatro · 5 cinco · 6 seis · 7 siete · 8 ocho · 9 nueve · 10 diez.", "11 once · 12 doce · 13 trece · 14 catorce · 15 quince · 20 veinte · 30 treinta · 100 cien(to).", "¿Qué hora es? — Es la una (1:00) · Son las dos/tres… (all other hours use “son las”).", "Days: lunes, martes, miércoles, jueves, viernes, sábado, domingo — not capitalized in Spanish."]}, {"h": "Sentence builders", "items": ["<b>Me gusta</b> + infinitive = I like to… (Me gusta leer.)", "<b>Quiero / Necesito / Tengo que</b> + infinitive = I want / need / have to…", "Word order mirrors English more than you fear: subject + verb + rest.", "Adjectives come AFTER the noun and must match gender/number: el libro rojo, las casas rojas.", "Negate by putting <b>no</b> before the verb: No entiendo = I don’t understand."]}], "example": {"t": "Build a sentence from parts", "lines": ["Quiero (I want) + estudiar (to study) + porque (because) + tengo (I have) + un examen mañana (a test tomorrow).", "“Quiero estudiar porque tengo un examen mañana.” — four memorized chunks, one real sentence."]}, "why": "Spanish runs on patterns, not memorization — learn the verb endings once and you can build thousands of sentences you have never seen."}, {"id": "study", "title": "Study Skills", "subject": "Study Skills", "icon": "🧠", "kw": "study skills memory focus test prep recall pomodoro plan review habits", "blurb": "The evidence-backed moves that make studying actually stick — recall, spacing, focus, and test-day tactics.", "groups": [{"h": "Before you study", "items": ["Set a target: “By 8:30 I can explain photosynthesis without looking.” Vague goals produce vague sessions.", "Gather everything first — book, notes, water — so getting up never becomes the break.", "Phone in another room. Not face-down: another room. Willpower loses to proximity.", "Start with the hardest subject while your brain is freshest."]}, {"h": "Active recall moves", "items": ["<b>Close the book and write what you remember.</b> Retrieval is the workout; re-reading is just watching.", "Flashcards with honest sorting: Know / Still Learning — and rate them so spaced repetition schedules the rematch.", "<b>Teach it:</b> explain the topic out loud like the listener is 10. Every stumble marks a gap.", "Practice questions beat highlighting. If your notes are all yellow, nothing stands out.", "Mix subjects in rotation (interleaving) — it feels harder and works better."]}, {"h": "Focus system", "items": ["<b>Pomodoro:</b> 25 minutes on, 5 off. After four rounds, take a longer break.", "Space sessions across days — three 30-minute sessions beat one 90-minute cram for anything you must keep.", "Review new material within 24 hours; that second pass is where forgetting gets beaten.", "Sleep is a study tool: memory consolidates overnight. The all-nighter taxes tomorrow’s test to pay for tonight’s."]}, {"h": "Test-day playbook", "items": ["Read every question twice; circle command words (explain, compare, justify) — they set the answer shape.", "Easy questions first — bank the points, build momentum, let hard ones simmer.", "Stuck? Mark it, move on, come back. One question is never worth five others.", "Use leftover time to check the questions you marked — fresh eyes catch dumb errors."]}], "example": {"t": "A 25-minute session, minute by minute", "lines": ["0–2 min: write the session target at the top of the page.", "2–20 min: closed-book recall + flashcards on the weakest topic only.", "20–25 min: check against notes, write down the 3 gaps — those open tomorrow’s session."]}, "why": "Your brain keeps what it retrieves, not what it rereads — testing yourself is the study method the research keeps crowning."}], "guides": [{"subject": "Science", "items": [{"t": "The Erupting Volcano Lab", "h": "It erupts on command — and you control the eruption size with science.", "m": ["Baking soda", "Vinegar", "Dish soap", "Red/yellow food coloring", "Plastic bottle", "Flour + salt + water (dough)", "Tray"], "s": ["Build the volcano cone from dough around the bottle on the tray.", "Paint it like real rock with lava streaks.", "Add 3 tbsp baking soda, a squirt of dish soap, and coloring into the bottle.", "Pour in 1/2 cup vinegar and step back.", "Test round 2: change ONE thing (more soap = foamier) and compare."], "b": "Title top-center. Left panel: question + hypothesis. Center: volcano photo. Right panel: what happened + why (the acid + base reaction makes CO₂ gas).", "sc": "This is my volcano. When vinegar — an acid — meets baking soda — a base — it creates carbon dioxide gas. The gas has to escape, so it pushes the lava out, just like pressure pushes real magma up.", "time": "1 afternoon (about 2 hours)"}, {"t": "Solar System Scale Walk", "h": "The planets, spaced for real — your hallway becomes space.", "m": ["Tape measure", "Index cards", "Markers", "String", "Small balls/objects of different sizes"], "s": ["Put the Sun card at one end of a hallway or yard.", "Place each planet at its scaled distance (look up the scale: about 1 step per planet works indoors).", "Write one wow fact per planet card.", "Photograph the walk for your board."], "b": "Title across the top. A photo strip of the walk runs the middle. Facts table at the bottom: planet, size, distance, one wow fact.", "sc": "Space is mostly EMPTY. In my model, the planets are tiny and the distances are huge — that emptiness is the real lesson.", "time": "About 1 hour"}, {"t": "Paper Towel Absorption Trials", "h": "A real experiment with a winner — brands go head to head.", "m": ["3 paper towel brands", "Water", "Measuring cup", "Tray", "Timer", "Ruler"], "s": ["Cut equal squares of each brand.", "Dip each in the same amount of water for 10 seconds.", "Measure how much water each absorbed (squeeze into the cup).", "Repeat 3 times per brand and average.", "Graph the results."], "b": "Question + hypothesis left. Bar graph center (judges love graphs). Conclusion right: which won and why you think so.", "sc": "I tested which paper towel absorbs the most. I ran every brand three times so one lucky dip couldn’t fool me. The winner was…", "time": "About 90 minutes"}, {"t": "Build a Working Lung Model", "h": "Pull the balloon and the \"lung\" breathes. It moves — judges stop walking.", "m": ["Plastic bottle (cut in half)", "2 balloons", "Straw", "Tape", "Modeling clay"], "s": ["Push the straw through the bottle neck, attach a balloon to the inside end — that’s the lung.", "Seal with clay.", "Stretch the second balloon over the cut bottom — that’s the diaphragm.", "Pull the bottom balloon down: the lung inflates. Push up: it deflates."], "b": "Diagram center with labels (trachea, lung, diaphragm). Left: how breathing works. Right: what happens with asthma, in simple words.", "sc": "When I pull the diaphragm down, air rushes in and the lung fills — exactly like your chest, every few seconds, all day.", "time": "About 1 hour"}, {"t": "Egg Drop Engineering Challenge", "h": "Your egg survives a staircase drop — or the redesign montage saves the day.", "m": ["Raw eggs", "Straws", "Tape", "Cotton balls", "Small box", "Rubber bands"], "s": ["Design a protective capsule using only your materials.", "Sketch the design first (judges reward plans).", "Drop from knee height, then waist, then staircase.", "After any crack, write what failed and redesign.", "Final drop + results."], "b": "Design sketch left. Drop-test results table center. \"What I changed and why\" right — the engineering story.", "sc": "Engineers don’t get it right first — they test, break, and improve. My capsule survived because…", "time": "1–2 hours"}, {"t": "Plant Growth: Light vs Dark", "h": "Two identical plants, one variable — a week of real data.", "m": ["2 bean seeds", "2 cups + soil", "Water", "Ruler", "Sunny window + dark closet"], "s": ["Plant both seeds the same way on the same day.", "One lives on the windowsill, one in the dark. Same water for both.", "Measure and photograph daily for 7 days.", "Chart both growth lines."], "b": "Daily photo strip across the middle. Growth chart bottom. Conclusion: what plants actually need.", "sc": "Both plants got the same water and soil. The only difference was light — and look at the chart. That’s how you know light caused it.", "time": "15 min setup + 5 min/day for a week"}]}, {"subject": "History", "items": [{"t": "Ancient Egypt Pyramid Diorama", "h": "A pyramid you build, with a hidden tomb chamber inside.", "m": ["Foam board or cardboard", "Sandpaper (for stone texture)", "Paint", "Small box (tomb)", "Toy figures or clay"], "s": ["Build the pyramid shape with a removable side panel.", "Add the hidden tomb chamber with \"treasure\" inside.", "Texture the outside with sandpaper + paint.", "Label: Nile River, sphinx, burial chamber."], "b": "Title top. Left: why pyramids were built. Right: 3 facts + how workers built them without machines.", "sc": "Pyramids weren’t just tombs — they were statements of power. Inside mine is the pharaoh’s chamber, protected exactly where the real ones hid theirs.", "time": "About 2 hours"}, {"t": "Timeline Scroll: A Century Unrolled", "h": "A 6-foot scroll of history they unroll like a treasure map.", "m": ["Long paper roll or taped sheets", "Markers", "Ruler", "Printed mini pictures"], "s": ["Mark equal spaces for each decade.", "Pick the 10 biggest events — one per decade.", "Draw or paste an image + 2-sentence summary for each.", "Roll it up with a ribbon for presentation day."], "b": "This IS the display — unroll it across the board or table. Title card at the start of the scroll.", "sc": "History isn’t a list — it’s a chain. This event caused that one. Watch the chain unroll.", "time": "About 90 minutes"}, {"t": "Revolutionary War Hero Trading Cards", "h": "Trading cards for historical figures — collectible history.", "m": ["Card stock", "Markers/colored pencils", "Ruler", "Clear sleeves (optional)"], "s": ["Pick 6 figures from both sides.", "Front: portrait + name. Back: stats — role, biggest moment, famous quote.", "Rate each: Leadership /10, Impact /10.", "Trade or quiz classmates with them."], "b": "Cards fanned across the board. Title top. One \"featured hero\" card enlarged in the center.", "sc": "Every hero has stats — just like athletes. This one changed the war with a single decision…", "time": "About 1 hour"}, {"t": "Museum Box: Artifact & Story", "h": "A shoebox museum — lift the lid, enter the exhibit.", "m": ["Shoebox", "Printed photos", "Labels on card stock", "Small replica objects"], "s": ["Choose one event or era.", "Create 4 \"artifacts\" (replicas/drawings) with museum labels.", "Arrange like a real exhibit with a title card.", "Write the 1-paragraph \"curator’s note.\""], "b": "The box is the display. Add a poster beside it: the era in 5 key facts.", "sc": "Museums tell stories with objects. Each artifact in my box proves one part of the story…", "time": "About 2 hours"}, {"t": "Interview a Generation (Oral History)", "h": "Real quotes from a real person who lived it — no textbook can beat it.", "m": ["Phone (voice recorder)", "Notebook", "5 prepared questions"], "s": ["Pick someone who lived through your era/event.", "Ask your 5 questions; record with permission.", "Pull the 3 best quotes.", "Build the board around the quotes + photos."], "b": "Big quote in the center. Timeline left. \"What I learned\" reflection right.", "sc": "Textbooks tell you what happened. This person was THERE. Here’s what they remember…", "time": "1 hour + interview time"}, {"t": "Map the Movement: Migration & Trade Routes", "h": "Yarn-and-pins map showing how people and goods actually moved.", "m": ["Large map printout or drawn map", "Yarn/string", "Pins", "Legend cards"], "s": ["Draw or print your region’s map big.", "Pin start/end points of the routes.", "Run yarn along each route; color-code by what moved (people, gold, spices, ideas).", "Write the legend explaining each color."], "b": "The map IS the board. Legend bottom-right. Title top-left.", "sc": "History moves. People, goods, and ideas traveled these lines — and changed both ends forever.", "time": "About 90 minutes"}]}, {"subject": "English / Reading", "items": [{"t": "Book-in-a-Box Diorama", "h": "Open the box: the book’s most important scene, in 3D.", "m": ["Shoebox", "Construction paper", "Glue", "Small figures or clay", "Markers"], "s": ["Pick the scene the whole book turns on.", "Build it inside the box — setting, characters, the moment.", "Write a scene label: what’s happening and why it matters.", "Add the book cover info on the outside."], "b": "The box is the star. Poster beside it: characters, conflict, theme in one sentence each.", "sc": "This is the moment everything changes in the story. If you understand this scene, you understand the book.", "time": "About 2 hours"}, {"t": "Character Social Media Profile", "h": "Your character, but make it a profile — bio, posts, and all.", "m": ["Poster board", "Printed/drawn photos", "Markers"], "s": ["Create the character’s profile: handle, bio, profile pic.", "Write 4 posts the character would actually post — in their voice.", "Add comments from other characters.", "Every post must prove something true about the character."], "b": "One big phone-shaped board. Profile top, posts below like a feed.", "sc": "If this character had a phone, this is exactly what they’d post — and every post is backed by the book.", "time": "About 1 hour"}, {"t": "Story Map Storyboard", "h": "The whole plot as a comic strip — beginning to theme.", "m": ["Poster board", "Ruler", "Markers/colored pencils"], "s": ["Draw 6 panels: setup, problem, rising action, climax, falling action, resolution.", "One drawing + one caption per panel.", "Underline the climax panel in red — biggest moment.", "Add the theme as the title."], "b": "Panels in a row like a comic. Title = the theme.", "sc": "Stories have a shape. Watch it rise to this panel — the climax — then land.", "time": "About 90 minutes"}, {"t": "Poetry Slam Poster", "h": "One poem, performed — with the poster as your stage backdrop.", "m": ["Poster board", "Markers", "Printed poem"], "s": ["Pick (or write) a poem with a strong feeling.", "Design the poster around the poem’s biggest image.", "Mark the lines you’ll say loudest.", "Practice performing it 3 times out loud."], "b": "Poem centered big. The key image drawn large behind/around it.", "sc": "Poetry is meant to be heard. Listen for this line — it’s the whole poem in one breath.", "time": "About 1 hour"}, {"t": "Author Detective Board", "h": "String-and-pins board connecting an author’s life to their book.", "m": ["Poster board", "String/yarn", "Pins", "Printed facts"], "s": ["Research 5 facts about the author’s life.", "Find 5 matching moments in the book.", "Pin facts on the left, book moments on the right, connect with string.", "Write the conclusion: how their life shaped the story."], "b": "Detective-board style. Title: \"The Case of the Author.\"", "sc": "Authors hide their lives inside their books. I connected the evidence — here’s the proof.", "time": "About 90 minutes"}, {"t": "Design a New Book Cover + Blurb", "h": "Rebrand the book like a designer — cover, blurb, and pitch.", "m": ["Card stock", "Art supplies", "The book"], "s": ["Design a cover that shows the theme, not just a scene.", "Write a back-cover blurb (no spoilers past chapter 3).", "Add 2 fake review quotes (\"A gut-punch of a book.\" — you, probably).", "Present why your cover sells the story better."], "b": "Cover huge in the center. Blurb beside it like a real back cover.", "sc": "You DO judge a book by its cover. Mine shows the theme — here’s why that sells the story.", "time": "About 1 hour"}]}, {"subject": "Math", "items": [{"t": "Math in My Room: Measurement Hunt", "h": "Your bedroom, measured and mapped to scale — real math, real room.", "m": ["Tape measure", "Graph paper", "Pencil", "Calculator"], "s": ["Measure your room and 5 objects in it.", "Draw the room to scale on graph paper (1 square = 10 cm).", "Calculate the area of the floor and one wall.", "Label every measurement on the drawing."], "b": "Scale drawing center. Measurement table right. \"Math I used\" list left.", "sc": "Math isn’t just worksheets — it measured my whole room. Here’s the area, the scale, and the proof.", "time": "About 1 hour"}, {"t": "Survey & Graph It: Class Favorites", "h": "Real data from real classmates, graphed like a pro.", "m": ["Survey questions", "Tally sheet", "Poster board", "Markers"], "s": ["Write one great question with 4–5 choices.", "Survey at least 20 people; tally carefully.", "Build a bar graph AND a pie chart of the same data.", "Write 2 conclusions the data actually supports."], "b": "Bar graph left, pie chart right. Title = your most surprising finding.", "sc": "I asked 20 people and the results surprised me. The graphs prove it — look at this bar.", "time": "About 90 minutes"}, {"t": "Budget a Dream Party ($100 Challenge)", "h": "A full party plan that must fit $100 — every dollar defended.", "m": ["Store flyers/prices", "Calculator", "Poster board"], "s": ["Set the menu, decorations, and activity list.", "Price every item for real.", "Add it up; if over $100, make cuts and show them.", "Present the final budget table."], "b": "Budget table center. Menu left. \"Hardest cut I made\" note right — teachers love that honesty.", "sc": "A budget is math with consequences. Here’s my party — and here’s exactly what I cut to make $100 work.", "time": "About 1 hour"}, {"t": "Geometry Photo Safari", "h": "Angles and shapes hiding in the real world — caught on camera.", "m": ["Phone/camera", "Protractor", "Printed photos"], "s": ["Photograph 8 shapes/angles around your home or school.", "Measure 3 of the angles with a protractor.", "Label each photo: shape name + one property.", "Arrange as a safari board."], "b": "Photos in a grid. Labels under each. Title top.", "sc": "Geometry isn’t in the textbook — it’s in every doorway and window. I caught 8 of them.", "time": "About 1 hour"}, {"t": "Fraction Pizza Restaurant", "h": "A menu where every dish teaches fractions — and the bill proves it.", "m": ["Cardboard (pizza circles)", "Markers", "Menu card"], "s": ["Draw pizzas cut into halves, thirds, fourths, eighths.", "Build a menu: each item is a fraction combo (\"1/2 pepperoni + 1/4 veggie\").", "Write 3 customer orders and solve the totals.", "Present the menu like a real restaurant."], "b": "Big pizza visuals center. Menu right. Solved orders left.", "sc": "Welcome to Fraction Pizza. Your order is a math problem — and I can solve it deliciously.", "time": "About 90 minutes"}, {"t": "Build a Bridge: Weight Test", "h": "Popsicle-stick bridge vs. stacks of books — engineering math.", "m": ["Popsicle sticks", "Glue", "Books (weights)", "Ruler"], "s": ["Design a bridge spanning 30 cm.", "Build it; let the glue dry fully.", "Stack books one at a time until it fails; count.", "Calculate: books held × weight each = total strength."], "b": "Photo of the bridge center. Strength results table right. Design sketch left.", "sc": "My bridge held this much weight. The math: triangles are the strongest shape — here’s where I used them.", "time": "About 2 hours"}]}, {"subject": "Art", "items": [{"t": "Recycled Sculpture", "h": "Trash becomes art — a sculpture with a message.", "m": ["Clean recyclables", "Glue/tape", "Paint"], "s": ["Collect clean bottles, boxes, cans for a week.", "Sketch the sculpture first.", "Build, then paint.", "Write the artist statement: what it means."], "b": "Photo/sculpture center. Artist statement right. \"Materials saved from landfill\" list left.", "sc": "This was all trash last week. Art is seeing what something could become.", "time": "About 2 hours"}, {"t": "Color Wheel in Real Objects", "h": "A color wheel built from actual stuff — no paint required.", "m": ["Poster board", "Household objects/photos", "Glue"], "s": ["Draw a big color wheel.", "Find real objects or photos for every color.", "Arrange by the wheel: primary, secondary, complementary.", "Label the color relationships."], "b": "The wheel IS the board. Labels around the rim.", "sc": "Colors have relationships. Opposite colors — complements — make each other pop. See?", "time": "About 1 hour"}, {"t": "Self-Portrait in a New Style", "h": "Your face, Picasso-style (or anime, or pop art) — artist’s choice.", "m": ["Paper/canvas", "Paint or markers", "Mirror"], "s": ["Pick an art style and study 2 examples.", "Sketch your portrait in that style.", "Finish with color.", "Write: what the style changed about how you look."], "b": "Portrait center. Small style examples + your notes beside it.", "sc": "Same face, new style. This style breaks one rule on purpose — here’s the rule and why breaking it works.", "time": "About 90 minutes"}, {"t": "Comic Strip: A Day in My Life", "h": "Six panels, one ordinary day, made legendary.", "m": ["Paper", "Ruler", "Pens/markers"], "s": ["Pick the 6 moments of one day.", "Draw panels with speech bubbles.", "Add one joke or surprise in panel 5.", "Ink and color the final."], "b": "Panels across the board like a newspaper comic.", "sc": "Comics are timing. The pause before this panel is where the laugh lives.", "time": "About 1 hour"}, {"t": "Shadow & Light Photo Series", "h": "Five photos where the shadow is the star.", "m": ["Phone/camera", "Lamp/sunlight", "Printed photos"], "s": ["Hunt dramatic shadows at different times of day.", "Shoot 10, pick the best 5.", "Print and arrange dark → light.", "Caption each: where the light came from."], "b": "Photo row center. Captions below each.", "sc": "Photographers don’t capture objects — they capture light. The shadows tell the story here.", "time": "About 1 hour"}, {"t": "Design a Logo for Something Real", "h": "A real logo for a real thing — club, team, or your own brand.", "m": ["Paper", "Markers or free design app", "Examples to study"], "s": ["Pick the brand (school club, team, family business).", "Sketch 5 rough ideas; pick the strongest.", "Draw the final big and clean.", "Write why each choice (shape, color, letter) fits."], "b": "Final logo huge center. Sketches small below — judges love seeing the process.", "sc": "A logo is a promise in one picture. Every choice in mine means something — here’s what.", "time": "About 90 minutes"}]}, {"subject": "Geography", "items": [{"t": "Salt-Dough Country Map", "h": "A 3D map you can touch — mountains rise, rivers run blue.", "m": ["Flour + salt + water", "Cardboard base", "Paint", "Toothpick flags"], "s": ["Draw the country’s outline on the base.", "Build landforms with salt dough (2 cups flour, 1 cup salt, 1 cup water).", "Paint: green lowlands, brown mountains, blue rivers.", "Flag the capital and 3 key cities."], "b": "The map is the display. Legend + 5 country facts on a side card.", "sc": "You can FEEL this map. The mountains rise where the real ones do — that’s why people settled here, by the rivers.", "time": "About 2 hours + drying"}, {"t": "Weather Station Week", "h": "Your backyard weather lab — 7 days of real data.", "m": ["Thermometer", "Rain gauge (jar + ruler)", "Notebook", "Poster board"], "s": ["Record temperature and rainfall at the same time daily.", "Note cloud types with drawings.", "Graph the week’s temperatures.", "Compare with the forecast — who was righter?"], "b": "Temperature graph center. Daily log table left. Forecast-vs-real verdict right.", "sc": "I ran a weather station for a week. Here’s where the forecast nailed it — and where my backyard beat it.", "time": "10 min/day for a week"}, {"t": "Landform Diorama", "h": "Five landforms in one box — a tiny world with labels.", "m": ["Box", "Clay or salt dough", "Paint", "Labels"], "s": ["Build: mountain, valley, plain, plateau, coastline.", "Paint each distinctly.", "Label with toothpick flags.", "Add one sentence per landform: how it forms."], "b": "Diorama center stage. Fact card beside it.", "sc": "Earth sculpts itself — water, wind, and pressure. Each landform here has a different sculptor.", "time": "About 90 minutes"}, {"t": "My Neighborhood Map (Cartographer Style)", "h": "A hand-drawn map of your world — landmarks, legend, compass rose.", "m": ["Large paper", "Ruler", "Colored pencils"], "s": ["Walk or picture your neighborhood boundaries.", "Draw streets to rough scale.", "Add 6 landmarks with symbols + a legend.", "Draw a compass rose and a scale bar."], "b": "The map fills the board. Legend bottom-right, compass top-right.", "sc": "Cartographers turn places into information. This is my world, mapped properly.", "time": "About 1 hour"}, {"t": "Continent Postcard Collection", "h": "Seven postcards, seven continents — a world tour in a box.", "m": ["Card stock", "Markers", "Printed images"], "s": ["One postcard per continent: front = famous place, back = 3 facts + a \"wish you were here\" note.", "Include climate and one animal per continent.", "Display fanned in a travel box."], "b": "Postcards fanned across the board over a world map outline.", "sc": "Seven continents, seven postcards. This one surprised me most — here’s why.", "time": "About 90 minutes"}, {"t": "River in a Tray: Erosion Lab", "h": "Pour water, watch a river carve its valley live.", "m": ["Tray", "Sand/soil", "Water jug", "Small rocks"], "s": ["Build a sand slope in the tray with a channel.", "Pour water slowly at the top.", "Watch erosion and where sediment lands (the delta).", "Photograph before/during/after."], "b": "Photo sequence center. \"What changed\" arrows on each photo.", "sc": "Rivers are sculptors with patience. In two minutes, my tray showed what takes the Colorado River centuries.", "time": "About 45 minutes"}]}]};

// DONEZO LIBRARY VIEWS (Nov 20) — homes for the Nov 19 verified content that
// had no renderer in this build: 42 concepts, 11 cheat sheets, 36 project
// guides. Data above is generated from ours-globals.json by
// build-library-data.py — do not hand-edit the data block.
section('concepts', 'Concept Library', '❖', 'Plain-language explainers for the ideas behind the homework.');
section('sheets', 'Cheat Sheets', '▩', 'One-page formula and rule sheets for every core subject.');
section('guides', 'Project Guides', '✎', 'Step-by-step project builds with materials, presentation and what to say.');

const libraryTitle = name => name.charAt(0).toUpperCase() + name.slice(1);
const stripTags = html => String(html ?? '').replace(/<[^>]*>/g, ' ');
function libraryIndex() {
  const index = [];
  for (const group of LIBRARY_DATA.concepts)
    for (const [name, concept] of group.items)
      index.push({lib: 'Concept Library', route: 'concepts', title: libraryTitle(name),
        text: (name + ' ' + concept.t + ' ' + concept.w).toLowerCase()});
  for (const sheet of LIBRARY_DATA.sheets) {
    const body = sheet.groups.map(g => g.h + ' ' + g.items.map(stripTags).join(' ')).join(' ');
    index.push({lib: 'Cheat Sheets', route: 'sheets', title: sheet.title,
      text: (sheet.title + ' ' + sheet.subject + ' ' + sheet.kw + ' ' + sheet.blurb + ' ' + body).toLowerCase()});
  }
  for (const group of LIBRARY_DATA.guides)
    for (const guide of group.items)
      index.push({lib: 'Project Guides', route: 'guides', title: guide.t,
        text: (guide.t + ' ' + group.subject + ' ' + guide.h + ' ' + guide.m.join(' ') + ' ' + guide.s.join(' ')).toLowerCase()});
  if (typeof strategies !== 'undefined')
    for (const name of Object.keys(strategies))
      index.push({lib: 'Strategy Cards · Test Prep', route: 'test', title: name,
        text: (name + ' ' + strategies[name]).toLowerCase()});
  return index;
}
let libraryCache = null;
function librarySearchPanel() {
  return '<section class="panel stack"><div class="split"><h2>Search the library</h2>' +
    '<label class="search">Search concepts, cheat sheets, guides and strategy cards' +
    '<input type="search" class="library-search" placeholder="Try algebra, volcano or photosynthesis"></label></div>' +
    '<div class="library-results" aria-live="polite"></div></section>';
}
function bindLibrarySearch() {
  const input = el('.library-search', main);
  const box = el('.library-results', main);
  if (!input || !box) return;
  input.addEventListener('input', () => {
    const query = input.value.trim().toLowerCase();
    if (!query) { box.innerHTML = ''; return; }
    libraryCache = libraryCache || libraryIndex();
    const hits = libraryCache.filter(entry => entry.text.includes(query)).slice(0, 20);
    box.innerHTML = hits.length
      ? '<ul class="task-list">' + hits.map(hit =>
          '<li><a href="#' + hit.route + '">' + esc(hit.title) + '</a><span>' + esc(hit.lib) + '</span></li>').join('') + '</ul>'
      : empty('No matches in the library. Try another word, or browse the full list below.');
  });
}
const conceptParagraphs = text => String(text ?? '').split(/\n+/).map(p => p.trim()).filter(Boolean)
  .map(p => '<p>' + esc(p) + '</p>').join('');

views.concepts = () => librarySearchPanel() + LIBRARY_DATA.concepts.map(group =>
  '<section class="panel"><h2>' + esc(group.subject) + '</h2>' + group.items.map(([name, concept]) =>
    '<details class="concept-entry"><summary>' + esc(libraryTitle(name)) + '</summary>' +
    conceptParagraphs(concept.t) +
    '<p><strong>Why it works:</strong> ' + esc(concept.w) + '</p></details>').join('') + '</section>').join('');
bindings.concepts = bindLibrarySearch;

views.sheets = () => librarySearchPanel() + LIBRARY_DATA.sheets.map(sheet =>
  '<section class="panel sheet-entry"><p class="eyebrow">' + esc(sheet.subject) + '</p>' +
  '<h2><span aria-hidden="true">' + esc(sheet.icon) + '</span> ' + esc(sheet.title) + '</h2>' +
  '<p>' + esc(sheet.blurb) + '</p>' + sheet.groups.map(group =>
    '<h3>' + esc(group.h) + '</h3><ul>' + group.items.map(item => '<li>' + item + '</li>').join('') + '</ul>').join('') +
  '</section>').join('');
bindings.sheets = bindLibrarySearch;

views.guides = () => librarySearchPanel() + LIBRARY_DATA.guides.map(group =>
  '<section class="panel"><h2>' + esc(group.subject) + '</h2>' + group.items.map(guide =>
    '<details class="guide-entry"><summary>' + esc(guide.t) + '</summary>' +
    '<p>' + esc(guide.h) + '</p><p><strong>Time:</strong> ' + esc(guide.time) + '</p>' +
    '<h3>Materials</h3><ul>' + guide.m.map(item => '<li>' + esc(item) + '</li>').join('') + '</ul>' +
    '<h3>Steps</h3><ol>' + guide.s.map(item => '<li>' + esc(item) + '</li>').join('') + '</ol>' +
    '<h3>Presentation</h3><p>' + esc(guide.b) + '</p>' +
    '<h3>What to say</h3><p>' + esc(guide.sc) + '</p></details>').join('') + '</section>').join('');
bindings.guides = bindLibrarySearch;

// Re-render once at load (same pattern as platform.js / wave6.js end-of-file
// show() calls): library.js loads last, so a direct landing on #concepts,
// #sheets or #guides renders correctly instead of "Page not found".
show();
